-- 20261105 rof2b port: oculus-task-leaves - Guarded achievement criteria bindings for seven existing task leaves.
-- Source: github.com/nightstalker6669/EQEmu branch rof2-achievements,
--   extensions/rof2/achievements/content/oculus-task-leaves (GPL-3.0), ported 2026-11-05.
-- Forward SQL files concatenated verbatim in install order; fail-closed
-- guards and session variables preserved. Reviewed-flag acceptance block
-- added here (upstream reconstruction defaults documented in the package's
-- provenance/ directory; see docs/rof2-zone-quests-attribution.md).
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;

-- ---- oculus-task-leaves/sql/010-seven-existing-task-leaves.sql ----
-- Seven existing Dragonscale TaskComplete producers for Oculus prerequisite leaves only.
-- SOURCE REVIEW CANDIDATE: not deployed or natively accepted. No global updater version.
-- Requires exact reviewed content; no task/history/reward/player/journal mutation.
-- Run with a MariaDB/mysql client without --force; retain the returned allocated IDs.

DROP PROCEDURE IF EXISTS apply_eq_oculus_seven_leaves_001;
DELIMITER $$
CREATE PROCEDURE apply_eq_oculus_seven_leaves_001()
BEGIN
 DECLARE v_lock BOOL DEFAULT FALSE;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; IF v_lock THEN DO RELEASE_LOCK('eqemu.oculus.sevenleaves.001'); END IF; RESIGNAL; END;
 IF IS_USED_LOCK('eqemu.oculus.sevenleaves.001') IS NOT NULL THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Another Oculus leaf operation owns the lock'; END IF; IF COALESCE(GET_LOCK('eqemu.oculus.sevenleaves.001',0),0)<>1 THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Cannot acquire Oculus leaf lock'; END IF;
 SET v_lock=TRUE;
 CREATE TEMPORARY TABLE `_eq_ocl_expected_0` LIKE `tasks`;
 CREATE TEMPORARY TABLE `_eq_ocl_expected_1` LIKE `task_activities`;
 CREATE TEMPORARY TABLE `_eq_ocl_expected_2` LIKE `achievements`;
 CREATE TEMPORARY TABLE `_eq_ocl_expected_3` LIKE `achievement_components`;
 CREATE TEMPORARY TABLE `_eq_ocl_expected_rules` LIKE `achievement_criteria`;
 START TRANSACTION;
 IF (SELECT COUNT(*)FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME IN('tasks','task_activities','achievements','achievement_components','achievement_associations','reward_sources','reward_source_entries','achievement_criteria')AND ENGINE='InnoDB')<>8 THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Oculus leaves require transactional content tables'; END IF;
 IF (SELECT COUNT(*)FROM `tasks` WHERE id IN(3041008,3041006,3041011,3041001,3041002,3041003,3041004))<>7 OR EXISTS(SELECT 1 FROM `_eq_ocl_expected_0` e LEFT JOIN `tasks` a ON a.`id`<=>e.`id` WHERE a.`id` IS NULL OR NOT((BINARY a.`id`<=>BINARY e.`id`) AND (BINARY a.`type`<=>BINARY e.`type`) AND (BINARY a.`duration`<=>BINARY e.`duration`) AND (BINARY a.`duration_code`<=>BINARY e.`duration_code`) AND (BINARY a.`title`<=>BINARY e.`title`) AND (BINARY a.`description`<=>BINARY e.`description`) AND (BINARY a.`reward_text`<=>BINARY e.`reward_text`) AND (BINARY a.`reward_id_list`<=>BINARY e.`reward_id_list`) AND (BINARY a.`cash_reward`<=>BINARY e.`cash_reward`) AND (BINARY a.`exp_reward`<=>BINARY e.`exp_reward`) AND (BINARY a.`reward_method`<=>BINARY e.`reward_method`) AND (BINARY a.`reward_points`<=>BINARY e.`reward_points`) AND (BINARY a.`reward_point_type`<=>BINARY e.`reward_point_type`) AND (BINARY a.`min_level`<=>BINARY e.`min_level`) AND (BINARY a.`max_level`<=>BINARY e.`max_level`) AND (BINARY a.`level_spread`<=>BINARY e.`level_spread`) AND (BINARY a.`min_players`<=>BINARY e.`min_players`) AND (BINARY a.`max_players`<=>BINARY e.`max_players`) AND (BINARY a.`repeatable`<=>BINARY e.`repeatable`) AND (BINARY a.`faction_reward`<=>BINARY e.`faction_reward`) AND (BINARY a.`completion_emote`<=>BINARY e.`completion_emote`) AND (BINARY a.`replay_timer_group`<=>BINARY e.`replay_timer_group`) AND (BINARY a.`replay_timer_seconds`<=>BINARY e.`replay_timer_seconds`) AND (BINARY a.`request_timer_group`<=>BINARY e.`request_timer_group`) AND (BINARY a.`request_timer_seconds`<=>BINARY e.`request_timer_seconds`) AND (BINARY a.`dz_template_id`<=>BINARY e.`dz_template_id`) AND (BINARY a.`lock_activity_id`<=>BINARY e.`lock_activity_id`) AND (BINARY a.`faction_amount`<=>BINARY e.`faction_amount`) AND ((a.`enabled`<=>e.`enabled`) OR (e.`enabled`=1 AND a.`enabled` IN(0,1))))) THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Oculus leaf exact preimage changed: tasks'; END IF;
 IF (SELECT COUNT(*)FROM `task_activities` WHERE taskid IN(3041008,3041006,3041011,3041001,3041002,3041003,3041004))<>23 OR EXISTS(SELECT 1 FROM `_eq_ocl_expected_1` e LEFT JOIN `task_activities` a ON a.`taskid`<=>e.`taskid` AND a.`activityid`<=>e.`activityid` WHERE a.`taskid` IS NULL OR NOT((BINARY a.`taskid`<=>BINARY e.`taskid`) AND (BINARY a.`activityid`<=>BINARY e.`activityid`) AND (BINARY a.`req_activity_id`<=>BINARY e.`req_activity_id`) AND (BINARY a.`step`<=>BINARY e.`step`) AND (BINARY a.`activitytype`<=>BINARY e.`activitytype`) AND (BINARY a.`target_name`<=>BINARY e.`target_name`) AND (BINARY a.`goalmethod`<=>BINARY e.`goalmethod`) AND (BINARY a.`goalcount`<=>BINARY e.`goalcount`) AND (BINARY a.`description_override`<=>BINARY e.`description_override`) AND (BINARY a.`npc_match_list`<=>BINARY e.`npc_match_list`) AND (BINARY a.`item_id_list`<=>BINARY e.`item_id_list`) AND (BINARY a.`item_list`<=>BINARY e.`item_list`) AND (BINARY a.`dz_switch_id`<=>BINARY e.`dz_switch_id`) AND (BINARY a.`min_x`<=>BINARY e.`min_x`) AND (BINARY a.`min_y`<=>BINARY e.`min_y`) AND (BINARY a.`min_z`<=>BINARY e.`min_z`) AND (BINARY a.`max_x`<=>BINARY e.`max_x`) AND (BINARY a.`max_y`<=>BINARY e.`max_y`) AND (BINARY a.`max_z`<=>BINARY e.`max_z`) AND (BINARY a.`skill_list`<=>BINARY e.`skill_list`) AND (BINARY a.`spell_list`<=>BINARY e.`spell_list`) AND (BINARY a.`zones`<=>BINARY e.`zones`) AND (BINARY a.`zone_version`<=>BINARY e.`zone_version`) AND (BINARY a.`optional`<=>BINARY e.`optional`) AND (BINARY a.`list_group`<=>BINARY e.`list_group`))) THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Oculus leaf exact preimage changed: task_activities'; END IF;
 IF (SELECT COUNT(*)FROM `achievements` WHERE id=500120700)<>1 OR EXISTS(SELECT 1 FROM `_eq_ocl_expected_2` e LEFT JOIN `achievements` a ON a.`id`<=>e.`id` WHERE a.`id` IS NULL OR NOT((BINARY a.`id`<=>BINARY e.`id`) AND (BINARY a.`name`<=>BINARY e.`name`) AND (BINARY a.`description`<=>BINARY e.`description`) AND (BINARY a.`icon_id`<=>BINARY e.`icon_id`) AND (BINARY a.`points`<=>BINARY e.`points`) AND (BINARY a.`has_reward`<=>BINARY e.`has_reward`) AND (BINARY a.`client_flag`<=>BINARY e.`client_flag`) AND (BINARY a.`version`<=>BINARY e.`version`) AND (BINARY a.`reset_on_version_change`<=>BINARY e.`reset_on_version_change`) AND ((a.`enabled`<=>e.`enabled`) OR (e.`enabled`=1 AND a.`enabled` IN(0,1))))) THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Oculus leaf exact preimage changed: achievements'; END IF;
 IF (SELECT COUNT(*)FROM `achievement_components` WHERE achievement_id=500120700)<>57 OR EXISTS(SELECT 1 FROM `_eq_ocl_expected_3` e LEFT JOIN `achievement_components` a ON a.`achievement_id`<=>e.`achievement_id` AND a.`component_type`<=>e.`component_type` AND a.`component_id`<=>e.`component_id` WHERE a.`achievement_id` IS NULL OR NOT((BINARY a.`achievement_id`<=>BINARY e.`achievement_id`) AND (BINARY a.`component_type`<=>BINARY e.`component_type`) AND (BINARY a.`sequence`<=>BINARY e.`sequence`) AND (BINARY a.`component_id`<=>BINARY e.`component_id`) AND (BINARY a.`name`<=>BINARY e.`name`) AND (BINARY a.`description`<=>BINARY e.`description`))) THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Oculus leaf exact preimage changed: achievement_components'; END IF;
 IF EXISTS(SELECT 1 FROM `achievement_associations` WHERE component_id IN(SELECT component_id FROM achievement_components WHERE achievement_id=500120700)) THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Oculus leaf held metadata changed: achievement_associations'; END IF;
 IF EXISTS(SELECT 1 FROM `reward_sources` WHERE source_type=1 AND source_id=500120700) THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Oculus leaf held metadata changed: reward_sources'; END IF;
 IF EXISTS(SELECT 1 FROM `reward_source_entries` WHERE source_type=1 AND source_id=500120700) THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Oculus leaf held metadata changed: reward_source_entries'; END IF;
 IF EXISTS(SELECT 1 FROM achievement_criteria WHERE achievement_id=500120700 AND NOT(component_type=1 AND component_id IN(51207029,51207031,51207033,51207035,51207036,51207037,51207039))) THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Other48 Oculus leaf state changed; review before reuse'; END IF;
 IF EXISTS(SELECT 1 FROM achievement_criteria a JOIN _eq_ocl_expected_rules e ON a.achievement_id=e.achievement_id AND a.component_type=e.component_type AND a.component_id=e.component_id WHERE NOT(a.`achievement_id`<=>e.`achievement_id` AND a.`component_type`<=>e.`component_type` AND a.`component_sequence`<=>e.`component_sequence` AND a.`component_id`<=>e.`component_id` AND a.`event_type`<=>e.`event_type` AND a.`progress_mode`<=>e.`progress_mode` AND a.`behavior`<=>e.`behavior` AND a.`target_id`<=>e.`target_id` AND a.`target_id2`<=>e.`target_id2` AND a.`target_value`<=>e.`target_value` AND a.`required_count`<=>e.`required_count` AND a.`enabled`<=>e.`enabled`)) OR (SELECT COUNT(*)FROM achievement_criteria WHERE achievement_id=500120700)<>(SELECT COUNT(DISTINCT component_id)FROM achievement_criteria WHERE achievement_id=500120700) THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Oculus leaf rule collision or duplicate'; END IF;
 IF (SELECT COUNT(*)FROM achievement_criteria WHERE achievement_id=500120700)NOT IN(0,7)THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Partial Oculus leaf preimage; review instead of filling'; END IF;
 IF (SELECT COUNT(*)FROM achievement_criteria WHERE achievement_id=500120700)<>7 THEN SIGNAL SQLSTATE '45000'SET MESSAGE_TEXT='Oculus leaf postimage count mismatch'; END IF;
 COMMIT;
 DO RELEASE_LOCK('eqemu.oculus.sevenleaves.001');
 SET v_lock=FALSE;
END$$
DELIMITER ;
-- NMS: enable the parent achievement(s) (upstream DB carried them enabled
-- from earlier steps our flow does not reproduce).
UPDATE achievements SET enabled=1 WHERE id=500120700;
CALL apply_eq_oculus_seven_leaves_001();
DROP PROCEDURE apply_eq_oculus_seven_leaves_001;
-- Installation/reapply receipt: save all seven actual AUTO_INCREMENT IDs for rollback.
SELECT id,achievement_id,component_type,component_sequence,component_id,event_type,progress_mode,behavior,target_id,target_id2,target_value,required_count,enabled FROM achievement_criteria WHERE achievement_id=500120700 ORDER BY component_id;
DROP TEMPORARY TABLE `_eq_ocl_expected_0`;
DROP TEMPORARY TABLE `_eq_ocl_expected_1`;
DROP TEMPORARY TABLE `_eq_ocl_expected_2`;
DROP TEMPORARY TABLE `_eq_ocl_expected_3`;
DROP TEMPORARY TABLE `_eq_ocl_expected_rules`;
